<?php namespace AISEO\REST; class Rest_Controller { public function register() { register_rest_route('ai-seo/v1','/generate',['methods'=>'POST','callback'=>[$this,'generate'],'permission_callback'=>[$this,'check_perm']]); } public function check_perm() { return current_user_can('manage_options'); } public function generate(\WP_REST_Request $r) { return new \WP_REST_Response(['status'=>'ok','provider'=>sanitize_text_field($r['provider']??'openai')]); } }
